#ifndef STATIC_CHECKER 
	if (unlikely(data_stack_frame_id != *id))
		return FALSE;
	*id = 0; 
#else
	unsigned int frame_id = (*id)->id;
	i_free_and_null(*id);

	if (unlikely(data_stack_frame_id != frame_id))
		return FALSE;
#endif 
	return TRUE;
}

