int
k5_utf16le_to_utf8(const uint8_t *utf16bytes, size_t nbytes, char **utf8_out)
{ 
    struct k5buf buf;
    struct k5input in;
    uint16_t ch1, ch2;
    krb5_ucs4 ch;
    size_t chlen;
    void *p; 

    *utf8_out = NULL;

    if (nbytes % 2 != 0) 
        return EINVAL;

    k5_buf_init_dynamic(&buf); 
    k5_input_init(&in, utf16bytes, nbytes); 
    while (!in.status && in.len > 0) { 

        ch1 = k5_input_get_uint16_le(&in); 
        if (IS_LOW_SURROGATE(ch1))
            goto invalid;
        if (IS_HIGH_SURROGATE(ch1)) { 

            ch2 = k5_input_get_uint16_le(&in);
            if (!IS_LOW_SURROGATE(ch2))
                goto invalid;
            ch = COMPOSE(ch1, ch2);
        } else {
            ch = ch1; 
        }

        chlen = krb5int_ucs4_to_utf8(ch, NULL); 
        p = k5_buf_get_space(&buf, chlen);
        if (p == NULL) 
            return ENOMEM;
        (void)krb5int_ucs4_to_utf8(ch, p); 
    }

    if (in.status) 
        goto invalid; 

    *utf8_out = k5_buf_cstring(&buf); 
    return (*utf8_out == NULL) ? ENOMEM : 0;

invalid:
    k5_buf_free(&buf);
    return EINVAL;
}

void
k5_buf_init_dynamic(struct k5buf *buf)
{ 
    buf->buftype = K5BUF_DYNAMIC; 
    buf->space = 128; 
    buf->data = malloc(buf->space);
    if (buf->data == NULL) { 
        set_error(buf);
        return;
    }
    buf->len = 0; 
}

size_t krb5int_ucs4_to_utf8(krb5_ucs4 c, char *buf)
{ 
    size_t len = 0;
    unsigned char *p = (unsigned char *) buf; 


    if (c > 0x10ffff)
        return 0;


    if (buf == NULL) { 
        if (c < 0x80) return 1; 
        else if (c < 0x800) return 2;
        else if (c < 0x10000) return 3;
        else return 4;
    }

    if (c < 0x80) {
        p[len++] = c;
    } else if (c < 0x800) {
        p[len++] = 0xc0 | ( c >> 6 );
        p[len++] = 0x80 | ( c & 0x3f );
    } else if (c < 0x10000) {
        p[len++] = 0xe0 | ( c >> 12 );
        p[len++] = 0x80 | ( (c >> 6) & 0x3f );
        p[len++] = 0x80 | ( c & 0x3f );
    } else  {
        p[len++] = 0xf0 | ( c >> 18 );
        p[len++] = 0x80 | ( (c >> 12) & 0x3f );
        p[len++] = 0x80 | ( (c >> 6) & 0x3f );
        p[len++] = 0x80 | ( c & 0x3f );
    }

    return len;
}

