	if (--channel->refcount > 0) 
		return 0;

#ifndef NO_IO_CACHE
	retval = flush_cached_blocks(channel, data, 0); 
#endif

	if (close(data->dev) < 0) 
		retval = errno;
	free_cache(data); 
#ifdef HAVE_PTHREAD 
	if (data->flags & IO_FLAG_THREADS) {
		pthread_mutex_destroy(&data->cache_mutex);
		pthread_mutex_destroy(&data->bounce_mutex);
		pthread_mutex_destroy(&data->stats_mutex);
	}
#endif

	ext2fs_free_mem(&channel->private_data); 
	if (channel->name)
		ext2fs_free_mem(&channel->name); 
	ext2fs_free_mem(&channel); 
	return retval; 
}

errcode_t ext2fs_zero_blocks2(ext2_filsys fs, blk64_t blk, int num,
			      blk64_t *ret_blk, int *ret_count) 
{
	int		j, count;
	static void	*buf;
	static int	stride_length;
	errcode_t	retval; 


	if (!fs) {
		if (buf) { 
			free(buf);
			buf = 0;
			stride_length = 0;
		}
		return 0; 
	}


	if (num <= 0)
		return 0;


	retval = io_channel_zeroout(fs->io, blk, num);
	if (retval == 0)
		return 0;


	if (num > stride_length && stride_length < MAX_STRIDE_LENGTH) {
		void *p;
		int new_stride = num;

		if (new_stride > MAX_STRIDE_LENGTH)
			new_stride = MAX_STRIDE_LENGTH;
		p = realloc(buf, fs->blocksize * new_stride);
		if (!p)
			return EXT2_ET_NO_MEMORY;
		buf = p;
		stride_length = new_stride;
		memset(buf, 0, fs->blocksize * stride_length);
	}

	j=0;
	while (j < num) {
		if (blk % stride_length) {
			count = stride_length - (blk % stride_length);
			if (count > (num - j))
				count = num - j;
		} else {
			count = num - j;
			if (count > stride_length)
				count = stride_length;
		}
		retval = io_channel_write_blk64(fs->io, blk, count, buf);
		if (retval) {
			if (ret_count)
				*ret_count = count;
			if (ret_blk)
				*ret_blk = blk;
			return retval;
		}
		j += count; blk += count;
	}
	return 0;
}

static void *t_malloc_real(size_t size, bool permanent)
{ 
	void *ret;
	size_t alloc_size;
	bool warn = FALSE; 
#ifdef DEBUG
	int old_errno = errno;
#endif

	if (unlikely(size == 0 || size > SSIZE_T_MAX)) 
		i_panic("Trying to allocate %zu bytes", size);

	if (unlikely(!data_stack_initialized)) { 

		data_stack_init();
	}
	block_canary_check(current_block); 


	alloc_size = ALLOC_SIZE(size); 
#ifdef DEBUG
	if(permanent) {
		current_frame->alloc_bytes += alloc_size;
		current_frame->alloc_count++;
	}
#endif
	data_stack_last_buffer_reset(TRUE); 

	if (permanent) { 

		current_frame->last_alloc_size = alloc_size;
	}

	if (current_block->left < alloc_size) { 
		struct stack_block *block;


		if (unused_block != NULL && unused_block->size >= alloc_size) {
			block = unused_block;
			unused_block = NULL;
			mem_block_reset(block);
		} else {

			block = mem_block_alloc(alloc_size);
			warn = TRUE;
		}


		block->prev = current_block;
		current_block->next = block;
		current_block = block;
	}


	ret = data_stack_after_last_alloc(current_block); 

#ifdef DEBUG
	if (current_block->left - alloc_size < current_block->left_lowwater)
		current_block->left_lowwater = current_block->left - alloc_size;
#endif
	if (permanent) 
		current_block->left -= alloc_size;

	if (warn) T_BEGIN { 

#ifdef DEBUG
		i_assert(errno == old_errno);
#else
		int old_errno = errno;
#endif

		data_stack_send_grow_event(alloc_size);

		errno = old_errno;
	} T_END;
#ifdef DEBUG
	memcpy(ret, &size, sizeof(size));
	ret = PTR_OFFSET(ret, MEM_ALIGN(sizeof(size)));

	memset(PTR_OFFSET(ret, size), CLEAR_CHR,
	       MEM_ALIGN(size + SENTRY_COUNT) - size);


	i_assert(errno == old_errno);
#endif
	return ret; 
}

void *t_malloc_no0(size_t size)
